        return !smatch(obj->value, value);
    case JSON_OP_LT:
        return scmp(obj->value, value) < 0;
    case JSON_OP_LE:
        return scmp(obj->value, value) <= 0;
    case JSON_OP_GT:
        return scmp(obj->value, value) > 0;
    case JSON_OP_GE:
        return scmp(obj->value, value) >= 0;
    case JSON_OP_MATCH:
        return scontains(obj->value, value) != 0;
    case JSON_OP_NMATCH:
        return scontains(obj->value, value) == 0;
    default:
        return 0;
    }
}

